import math


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def _is_finite_deep(value):
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, dict):
        return all(_is_finite_deep(v) for v in value.values())
    if isinstance(value, list):
        return all(_is_finite_deep(v) for v in value)
    return True


def _require_int(value, label):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("%s must be an integer" % label)
    return value


def _require_nonblank_str(value, label):
    if not isinstance(value, str):
        raise ValueError("%s must be a string" % label)
    if not value.strip():
        raise ValueError("%s must not be blank" % label)
    return value


def _require_str_list(value, label):
    if not isinstance(value, list):
        raise ValueError("%s must be a list" % label)
    for item in value:
        _require_nonblank_str(item, "%s entry" % label)
    return list(value)


_KIND_ORDER = {"revoke": 0, "issue": 1, "refresh": 2}
_KINDS = set(_KIND_ORDER)


def _validate_events(events):
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    records = []
    ids = set()
    issued_tokens = set()

    for event in events:
        if not isinstance(event, dict):
            raise ValueError("event entries must be objects")
        if "id" not in event or "ts" not in event or "kind" not in event or "token" not in event:
            raise ValueError("event missing a required field")

        event_id = _require_nonblank_str(event["id"], "event id")
        if event_id in ids:
            raise ValueError("duplicate event id: %s" % event_id)
        ids.add(event_id)

        ts = _require_int(event["ts"], "event ts")
        if ts < 0:
            raise ValueError("event ts must be >= 0")

        kind = event["kind"]
        if not isinstance(kind, str) or kind not in _KINDS:
            raise ValueError("invalid event kind")

        token = _require_nonblank_str(event["token"], "event token")

        record = {"id": event_id, "ts": ts, "kind": kind, "token": token}

        if kind == "issue":
            subject = _require_nonblank_str(event.get("subject"), "issue subject")
            if "subject" not in event:
                raise ValueError("issue event requires subject")
            subject = _require_nonblank_str(event["subject"], "issue subject")
            if "expires" not in event:
                raise ValueError("issue event requires expires")
            expires = _require_int(event["expires"], "issue expires")
            if expires <= ts:
                raise ValueError("issue expires must be greater than ts")
            if "groups" not in event:
                raise ValueError("issue event requires groups")
            groups = _require_str_list(event["groups"], "issue groups")
            record["subject"] = subject
            record["expires"] = expires
            record["groups"] = groups
            record["parent"] = None
        elif kind == "refresh":
            if "parent" not in event:
                raise ValueError("refresh event requires parent")
            parent = _require_nonblank_str(event["parent"], "refresh parent")
            if "expires" not in event:
                raise ValueError("refresh event requires expires")
            expires = _require_int(event["expires"], "refresh expires")
            if expires <= ts:
                raise ValueError("refresh expires must be greater than ts")
            record["parent"] = parent
            record["expires"] = expires
        else:  # revoke
            record["parent"] = None
            record["expires"] = None

        if kind in {"issue", "refresh"}:
            if token in issued_tokens:
                raise ValueError("token can only be issued or refreshed once: %s" % token)
            issued_tokens.add(token)

        records.append(record)

    return records


def _has_revoked_ancestor(token, tokens, revoked):
    current = token
    while current is not None:
        if current in revoked:
            return True
        record = tokens.get(current)
        if record is None:
            break
        current = record["parent"]
    return False


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    expected = len(contract.get("inputs", []))
    if len(payloads) != expected:
        raise ValueError("expected %d payloads, got %d" % (expected, len(payloads)))

    for payload in payloads:
        if not _is_finite_deep(payload):
            raise ValueError("payloads must contain only finite JSON numbers")

    data = _unwrap(payloads[0])
    if not isinstance(data, dict):
        raise ValueError("session payload must be an object")
    if "now" not in data or "events" not in data:
        raise ValueError("session payload requires now and events fields")

    now = _require_int(data["now"], "now")
    if now < 0:
        raise ValueError("now must be >= 0")

