        if record["ts"] > now:
            continue

        kind = record["kind"]
        token = record["token"]

        if kind == "revoke":
            revoked.add(token)
            continue

        if kind == "issue":
            tokens[token] = {
                "token": token,
                "subject": record["subject"],
                "groups": list(record["groups"]),
                "expires": record["expires"],
                "ts": record["ts"],
                "parent": None,
                "valid_creation": True,
                "superseded": False,
            }
            continue

