        parent_token = record["parent"]
        parent = tokens.get(parent_token)
        parent_ok = False
        if parent is not None:
            parent_ok = (
                parent["valid_creation"] is True
                and parent["superseded"] is False
                and parent["expires"] > record["ts"]
                and not _has_revoked_ancestor(parent_token, tokens, revoked)
            )

        child = {
            "token": token,
            "subject": None,
            "groups": None,
            "expires": record["expires"],
            "ts": record["ts"],
            "parent": parent_token,
            "valid_creation": parent_ok,
            "superseded": False,
        }

        if parent_ok:
            child["subject"] = parent["subject"]
            child["groups"] = list(parent["groups"])
            parent["superseded"] = True

        tokens[token] = child

    active = []
    invalid = []

    for record in tokens.values():
        bad = False
        if record["valid_creation"] is not True:
            bad = True
        elif record["superseded"] is True:
            bad = True
        elif _has_revoked_ancestor(record["token"], tokens, revoked):
            bad = True
        elif now >= record["expires"]:
            bad = True

        if bad:
            invalid.append(record["token"])
        else:
            active.append({
                "token": record["token"],
                "subject": record["subject"],
                "groups": sorted(set(record["groups"])),
                "expires": record["expires"],
            })

    active.sort(key=lambda item: item["token"])
    invalid.sort()
    revoked_list = sorted(revoked)

    return {
        "name": contract["name"],
        "result": {
            "active_tokens": active,
            "invalid_tokens": invalid,
            "revoked": revoked_list,
        },
    }

