def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    expected = len(contract.get("inputs", []))
    if len(payloads) != expected:
        raise ValueError("expected %d payloads, got %d" % (expected, len(payloads)))

    for payload in payloads:
        if not _is_finite_deep(payload):
            raise ValueError("payloads must contain only finite JSON numbers")

    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError("authorization payload must be an object")
    if "groups" not in raw or "rules" not in raw or "requests" not in raw:
        raise ValueError("authorization payload missing a required field")

    groups = _parse_groups(raw["groups"])
    rules = _parse_rules(raw["rules"])
    requests = _parse_requests(raw["requests"])

    schema_compatible = _parse_schema_result(_unwrap(payloads[1]))
    active_map = _parse_session_result(_unwrap(payloads[2]), groups)

    closures = _build_closures(groups)

    decisions = []
    for request in requests:
        if schema_compatible is False:
            decisions.append({
                "id": request["id"],
                "effect": "deny",
                "reason": "schema",
                "rule_id": None,
                "roles": [],
            })
            continue

        active = active_map.get(request["token"])
        if active is None:
            decisions.append({
                "id": request["id"],
                "effect": "deny",
                "reason": "session",
                "rule_id": None,
                "roles": [],
            })
            continue

        roles_set = _roles_for(groups, closures, active["groups"])
        roles = sorted(roles_set)

        matches = []
        for rule in rules:
            if (
                rule["role"] in roles_set
                and fnmatchcase(request["resource"], rule["resource"])
                and fnmatchcase(request["action"], rule["action"])
            ):
                matches.append(rule)

        denies = [rule for rule in matches if rule["effect"] == "deny"]
        allows = [rule for rule in matches if rule["effect"] == "allow"]

        if denies:
            winner = min(denies, key=lambda rule: rule["id"])
            decisions.append({
                "id": request["id"],
                "effect": "deny",
                "reason": "rule",
                "rule_id": winner["id"],
                "roles": roles,
            })
        elif allows:
            winner = min(allows, key=lambda rule: rule["id"])
            decisions.append({
                "id": request["id"],
                "effect": "allow",
                "reason": "rule",
                "rule_id": winner["id"],
                "roles": roles,
            })
        else:
            decisions.append({
                "id": request["id"],
                "effect": "deny",
                "reason": "default",
                "rule_id": None,
                "roles": roles,
            })

    allow_count = sum(1 for decision in decisions if decision["effect"] == "allow")
    deny_count = sum(1 for decision in decisions if decision["effect"] == "deny")

    return {
        "name": contract["name"],
        "result": {
            "decisions": decisions,
            "allow": allow_count,
            "deny": deny_count,
        },
    }

