import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _contracts():
    return sorted(
        p for p in ROOT.rglob("contract.json")
        if "outputs" not in p.relative_to(ROOT).parts
    )


def main():
    contract_paths = _contracts()
    if not contract_paths:
        raise SystemExit("no component contracts found")

    by_output = {}
    for path in contract_paths:
        contract = json.loads(path.read_text(encoding="utf-8"))
        output = str(Path(contract["output"]))
        if output in by_output:
            raise SystemExit("duplicate component output: %s" % output)
        by_output[output] = path

    dependencies = {}
    for path in contract_paths:
        contract = json.loads(path.read_text(encoding="utf-8"))
        deps = set()
        for input_path in contract["inputs"]:
            key = str(Path(input_path))
            if key in by_output and by_output[key] != path:
                deps.add(by_output[key])
        dependencies[path] = deps

    remaining = set(contract_paths)
    ordered = []
    while remaining:
        ready = sorted(
            [p for p in remaining if not (dependencies[p] & remaining)],
            key=lambda p: str(p),
        )
        if not ready:
            raise SystemExit("cyclic component dependency graph")
        for path in ready:
            ordered.append(path)
            remaining.remove(path)

    for path in ordered:
        render_script = path.parent / "render.py"
        subprocess.run(
            [sys.executable, str(render_script)],
            cwd=ROOT,
            check=True,
        )

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

