def _parse_session_result(value, groups):
    if not isinstance(value, dict):
        raise ValueError("session result must be an object")
    if "active_tokens" not in value or "invalid_tokens" not in value or "revoked" not in value:
        raise ValueError("session result missing a required field")

    active_tokens = value["active_tokens"]
    if not isinstance(active_tokens, list):
        raise ValueError("active_tokens must be a list")
    active_map = {}
    for item in active_tokens:
        if not isinstance(item, dict):
            raise ValueError("active token entries must be objects")
        if "token" not in item or "subject" not in item or "groups" not in item or "expires" not in item:
            raise ValueError("active token entry missing a required field")
        token = _require_nonblank_str(item["token"], "active token")
        subject = _require_nonblank_str(item["subject"], "active subject")
        token_groups = _require_str_list(item["groups"], "active groups")
        expires = _require_int(item["expires"], "active expires")
        if token in active_map:
            raise ValueError("duplicate active token: %s" % token)
        for group in token_groups:
            if group not in groups:
                raise ValueError("unknown group for active token: %s" % group)
        active_map[token] = {"token": token, "groups": token_groups}

    invalid_tokens = value["invalid_tokens"]
    if not isinstance(invalid_tokens, list):
        raise ValueError("invalid_tokens must be a list")
    for token in invalid_tokens:
        _require_nonblank_str(token, "invalid token")

    revoked = value["revoked"]
    if not isinstance(revoked, list):
        raise ValueError("revoked must be a list")
    for token in revoked:
        _require_nonblank_str(token, "revoked token")

    return active_map

